sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_AiToolUpdateBusinessProcess(vBusinessProcess,strDetails,vExpected)
	{
		function TestCase_AiToolUpdateBusinessProcess_CheckResult(vInput,vExpected,vResult)
		{
			if (x_snc_devtools.IsObject(vResult) == false)
			{
				return false;
			}

			if (vExpected == true)
			{
				if (x_snc_devtools.GetValue(vResult,'message') != 'Updating the Business Process details was successful!')
				{
					return false;
				}
				test.Log(GetBusinessProcessRecord(vBusinessProcess))
			}

			return true;
		}
		
		test.TestCase(
			'Function AiToolUpdateBusinessProcess()',
			AiToolUpdateBusinessProcess,
			{
				'vBusinessProcess': vBusinessProcess,
				'strDetails': strDetails
			},
			vExpected,
			TestCase_AiToolUpdateBusinessProcess_CheckResult);
	}
		
	TestCase_AiToolUpdateBusinessProcess(null,null,false);


	var grBP = new GlideRecord('x_snc_agenticbpc_business_process');
	grBP.initialize();
	grBP.name = 'Simple Task Process';
	grBP.description = 'Perform some work.';
	grBP.insert();
	
	TestCase_AiToolUpdateBusinessProcess(
		grBP.number,
		x_snc_devtools.MakeJson(x_snc_devtools.BusinessProcessGetExample()),
		true);
	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
